def compute(vars):
    provisions = vars["v1"]
    total_deferred_tax_assets = vars["v2"]
    output_meta = {
        "currency": None,
        "scale": None,
        "unit": "percentage"
    }

    if total_deferred_tax_assets == 0:
        return {
            "value": None,
            "trace": {
                "provisions": provisions,
                "total_deferred_tax_assets": total_deferred_tax_assets,
                "output_meta": output_meta
            }
        }

    ratio = provisions / total_deferred_tax_assets
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "provisions": provisions,
            "total_deferred_tax_assets": total_deferred_tax_assets,
            "ratio": ratio,
            "output_meta": output_meta
        }
    }

def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return {"value": None, "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }}
    value = numerator / denominator * 100
    return {
        "value": value,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": numerator / denominator,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }
    }

def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3

    if count == 0:
        return None

    total = v1 + v2 + v3
    average = total / count

    return {
        "value": average,
        "trace": {
            "values": [v1, v2, v3],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage of net revenues"
            }
        }
    }

def compute(vars):
    granted_2017_millions = vars["v1"]
    granted_2018_millions = vars["v2"]
    granted_2019_millions = vars["v3"] / 1000

    amounts_by_year = {
        2017: granted_2017_millions,
        2018: granted_2018_millions,
        2019: granted_2019_millions,
    }
    largest_year = max(amounts_by_year, key=amounts_by_year.get)

    return {
        "value": largest_year,
        "trace": {
            "granted_2017_millions": granted_2017_millions,
            "granted_2018_millions": granted_2018_millions,
            "granted_2019_millions": granted_2019_millions,
            "largest_amount_millions": amounts_by_year[largest_year],
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "year",
            },
        },
    }
